INSERT INTO fitness_exercise(id,data) VALUES('barbell-bench-press','{"id":"barbell-bench-press","nameZh":"杠铃卧推","nameEn":"Barbell Bench Press - Medium Grip","primaryMuscle":"胸大肌","secondaryMuscles":["肱三头肌","三角肌前束"],"equipment":["杠铃","卧推架"],"difficulty":"中级","locations":["健身房"],"type":"力量","pattern":"push","instructions":["仰卧在平凳上，双脚踩稳，肩胛保持稳定。","握紧杠铃，手腕与前臂对齐，缓慢下放到胸部附近。","保持臀部贴凳，将杠铃平稳推回起始位置。"],"commonMistakes":["杠铃在胸前弹起借力。","手腕后折或推起时臀部离凳。"],"mediaUrl":"/static/fitness/media/barbell-bench-press-0.jpg","mediaFrames":["/static/fitness/media/barbell-bench-press-0.jpg","/static/fitness/media/barbell-bench-press-1.jpg"],"muscleImageUrl":"","source":"Free Exercise DB；中文说明由本站整理","sourceUrl":"https://github.com/yuhonas/free-exercise-db/blob/a859101d633a01c4a1a920d6a8ce41dabba0705f/exercises/Barbell_Bench_Press_-_Medium_Grip.json","license":"Unlicense","recommendedSets":3,"repsMin":6,"repsMax":10,"durationSeconds":null}') ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO fitness_exercise(id,data) VALUES('incline-dumbbell-press','{"id":"incline-dumbbell-press","nameZh":"上斜哑铃卧推","nameEn":"Incline Dumbbell Press","primaryMuscle":"胸大肌","secondaryMuscles":["三角肌前束","肱三头肌"],"equipment":["哑铃","训练凳"],"difficulty":"初级","locations":["家里","宿舍","健身房"],"type":"力量","pattern":"push","instructions":["靠在上斜训练凳上，双脚踩稳，哑铃置于胸侧。","保持肩胛稳定，将哑铃向上推起。","控制速度下放，始终保持两侧动作协调。"],"commonMistakes":["凳背过陡导致主要变成肩推。","肩部耸起，或在底部失去控制。"],"mediaUrl":"/static/fitness/media/incline-dumbbell-press-0.jpg","mediaFrames":["/static/fitness/media/incline-dumbbell-press-0.jpg","/static/fitness/media/incline-dumbbell-press-1.jpg"],"muscleImageUrl":"","source":"Free Exercise DB；中文说明由本站整理","sourceUrl":"https://github.com/yuhonas/free-exercise-db/blob/a859101d633a01c4a1a920d6a8ce41dabba0705f/exercises/Incline_Dumbbell_Press.json","license":"Unlicense","recommendedSets":3,"repsMin":8,"repsMax":12,"durationSeconds":null}') ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO fitness_exercise(id,data) VALUES('dumbbell-shoulder-press','{"id":"dumbbell-shoulder-press","nameZh":"哑铃肩推","nameEn":"Dumbbell Shoulder Press","primaryMuscle":"三角肌","secondaryMuscles":["肱三头肌"],"equipment":["哑铃","训练凳"],"difficulty":"初级","locations":["家里","宿舍","健身房"],"type":"力量","pattern":"push","instructions":["坐稳并收紧腹部，哑铃放在肩侧。","前臂接近竖直，将哑铃推至头顶上方。","缓慢下降至可控、舒适的位置。"],"commonMistakes":["腰部过度后仰借力。","哑铃下降时手腕和肘部失去对齐。"],"mediaUrl":"/static/fitness/media/dumbbell-shoulder-press-0.jpg","mediaFrames":["/static/fitness/media/dumbbell-shoulder-press-0.jpg","/static/fitness/media/dumbbell-shoulder-press-1.jpg"],"muscleImageUrl":"","source":"Free Exercise DB；中文说明由本站整理","sourceUrl":"https://github.com/yuhonas/free-exercise-db/blob/a859101d633a01c4a1a920d6a8ce41dabba0705f/exercises/Dumbbell_Shoulder_Press.json","license":"Unlicense","recommendedSets":3,"repsMin":8,"repsMax":12,"durationSeconds":null}') ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO fitness_exercise(id,data) VALUES('lateral-raise','{"id":"lateral-raise","nameZh":"哑铃侧平举","nameEn":"Side Lateral Raise","primaryMuscle":"三角肌中束","secondaryMuscles":["斜方肌"],"equipment":["哑铃"],"difficulty":"初级","locations":["家里","宿舍","健身房"],"type":"力量","pattern":"push","instructions":["站稳，双手持哑铃垂在身体两侧，肘部微屈。","双臂向侧上方抬起至接近肩高。","保持躯干稳定，缓慢放回两侧。"],"commonMistakes":["用身体摆动甩起重量。","耸肩或抬得过高。"],"mediaUrl":"/static/fitness/media/lateral-raise-0.jpg","mediaFrames":["/static/fitness/media/lateral-raise-0.jpg","/static/fitness/media/lateral-raise-1.jpg"],"muscleImageUrl":"","source":"Free Exercise DB；中文说明由本站整理","sourceUrl":"https://github.com/yuhonas/free-exercise-db/blob/a859101d633a01c4a1a920d6a8ce41dabba0705f/exercises/Side_Lateral_Raise.json","license":"Unlicense","recommendedSets":3,"repsMin":12,"repsMax":20,"durationSeconds":null}') ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO fitness_exercise(id,data) VALUES('face-pull','{"id":"face-pull","nameZh":"绳索面拉","nameEn":"Face Pull","primaryMuscle":"三角肌后束","secondaryMuscles":["斜方肌","菱形肌"],"equipment":["龙门架 / 绳索器械"],"difficulty":"初级","locations":["健身房"],"type":"力量","pattern":"pull","instructions":["将绳索调至面部附近高度，握住绳端并站稳。","向面部拉绳，两手在脸侧分开，肘部向外。","停顿后缓慢伸臂，保持肩部下沉。"],"commonMistakes":["腰部后仰拉动重量。","耸肩或只用手臂快速拉扯。"],"mediaUrl":"/static/fitness/media/face-pull-0.jpg","mediaFrames":["/static/fitness/media/face-pull-0.jpg","/static/fitness/media/face-pull-1.jpg"],"muscleImageUrl":"","source":"Free Exercise DB；中文说明由本站整理","sourceUrl":"https://github.com/yuhonas/free-exercise-db/blob/a859101d633a01c4a1a920d6a8ce41dabba0705f/exercises/Face_Pull.json","license":"Unlicense","recommendedSets":2,"repsMin":12,"repsMax":20,"durationSeconds":null}') ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO fitness_exercise(id,data) VALUES('crunch','{"id":"crunch","nameZh":"卷腹","nameEn":"Crunches","primaryMuscle":"腹直肌","secondaryMuscles":[],"equipment":["徒手"],"difficulty":"初级","locations":["家里","宿舍","健身房","户外"],"type":"核心","pattern":"core","instructions":["仰卧屈膝，双脚平放地面。","呼气时卷起上背，让肋骨靠近骨盆。","控制还原，不必将整个躯干坐起。"],"commonMistakes":["双手拉扯颈部。","依靠摆动或把卷腹变成快速起坐。"],"mediaUrl":"/static/fitness/media/crunch-0.jpg","mediaFrames":["/static/fitness/media/crunch-0.jpg","/static/fitness/media/crunch-1.jpg"],"muscleImageUrl":"","source":"Free Exercise DB；中文说明由本站整理","sourceUrl":"https://github.com/yuhonas/free-exercise-db/blob/a859101d633a01c4a1a920d6a8ce41dabba0705f/exercises/Crunches.json","license":"Unlicense","recommendedSets":3,"repsMin":10,"repsMax":15,"durationSeconds":null}') ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO fitness_exercise(id,data) VALUES('squat','{"id":"squat","nameZh":"杠铃深蹲","nameEn":"Barbell Squat","primaryMuscle":"股四头肌","secondaryMuscles":["臀大肌","腘绳肌","竖脊肌"],"equipment":["杠铃","深蹲架"],"difficulty":"中级","locations":["健身房"],"type":"力量","pattern":"squat","instructions":["将杠铃稳定放在上背，双脚站稳，腹部收紧。","屈髋屈膝下蹲，膝盖与脚尖方向一致。","在能保持控制的深度停下，脚掌压地起身。"],"commonMistakes":["膝盖向内塌陷。","下蹲失去腰背稳定或脚跟离地。"],"mediaUrl":"/static/fitness/media/squat-0.jpg","mediaFrames":["/static/fitness/media/squat-0.jpg","/static/fitness/media/squat-1.jpg"],"muscleImageUrl":"","source":"Free Exercise DB；中文说明由本站整理","sourceUrl":"https://github.com/yuhonas/free-exercise-db/blob/a859101d633a01c4a1a920d6a8ce41dabba0705f/exercises/Barbell_Squat.json","license":"Unlicense","recommendedSets":3,"repsMin":6,"repsMax":10,"durationSeconds":null}') ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO fitness_exercise(id,data) VALUES('romanian-deadlift','{"id":"romanian-deadlift","nameZh":"罗马尼亚硬拉","nameEn":"Romanian Deadlift","primaryMuscle":"腘绳肌","secondaryMuscles":["臀大肌","竖脊肌"],"equipment":["杠铃"],"difficulty":"中级","locations":["健身房"],"type":"力量","pattern":"hinge","instructions":["站稳持杠，膝盖微屈，收紧腹部。","臀部向后移，杠铃贴近双腿下放。","在腿后侧有拉伸且背部仍稳定的位置停止，伸髋站起。"],"commonMistakes":["弯腰追求触地。","膝盖过度弯曲，将动作变成深蹲。"],"mediaUrl":"/static/fitness/media/romanian-deadlift-0.jpg","mediaFrames":["/static/fitness/media/romanian-deadlift-0.jpg","/static/fitness/media/romanian-deadlift-1.jpg"],"muscleImageUrl":"","source":"Free Exercise DB；中文说明由本站整理","sourceUrl":"https://github.com/yuhonas/free-exercise-db/blob/a859101d633a01c4a1a920d6a8ce41dabba0705f/exercises/Romanian_Deadlift.json","license":"Unlicense","recommendedSets":3,"repsMin":8,"repsMax":12,"durationSeconds":null}') ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO fitness_exercise(id,data) VALUES('bulgarian-split-squat','{"id":"bulgarian-split-squat","nameZh":"保加利亚分腿蹲","nameEn":"Split Squat with Dumbbells","primaryMuscle":"股四头肌","secondaryMuscles":["臀大肌","腘绳肌"],"equipment":["哑铃","训练凳"],"difficulty":"中级","locations":["家里","宿舍","健身房"],"type":"力量","pattern":"squat","instructions":["后脚放在稳定训练凳上，前脚踩稳，双手持哑铃。","屈前腿下蹲，保持前膝与脚尖同向。","前脚发力站起，完成一侧后换腿；目标次数按每腿计算。"],"commonMistakes":["前脚位置过窄导致失衡。","用后腿蹬起或前膝内扣。"],"mediaUrl":"/static/fitness/media/bulgarian-split-squat-0.jpg","mediaFrames":["/static/fitness/media/bulgarian-split-squat-0.jpg","/static/fitness/media/bulgarian-split-squat-1.jpg"],"muscleImageUrl":"","source":"Free Exercise DB；中文说明由本站整理","sourceUrl":"https://github.com/yuhonas/free-exercise-db/blob/a859101d633a01c4a1a920d6a8ce41dabba0705f/exercises/Split_Squat_with_Dumbbells.json","license":"Unlicense","recommendedSets":2,"repsMin":8,"repsMax":12,"durationSeconds":null}') ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO fitness_exercise(id,data) VALUES('leg-curl','{"id":"leg-curl","nameZh":"俯卧腿弯举","nameEn":"Lying Leg Curls","primaryMuscle":"腘绳肌","secondaryMuscles":["小腿肌群"],"equipment":["固定力量器械"],"difficulty":"初级","locations":["健身房"],"type":"力量","pattern":"hinge","instructions":["调整器械，使膝关节对齐转轴，滚垫位于小腿下端。","腹部与髋部贴稳支撑垫，屈膝卷起滚垫。","缓慢伸膝回到起始位置。"],"commonMistakes":["抬起髋部或拱腰借力。","快速甩动滚垫。"],"mediaUrl":"/static/fitness/media/leg-curl-0.jpg","mediaFrames":["/static/fitness/media/leg-curl-0.jpg","/static/fitness/media/leg-curl-1.jpg"],"muscleImageUrl":"","source":"Free Exercise DB；中文说明由本站整理","sourceUrl":"https://github.com/yuhonas/free-exercise-db/blob/a859101d633a01c4a1a920d6a8ce41dabba0705f/exercises/Lying_Leg_Curls.json","license":"Unlicense","recommendedSets":2,"repsMin":10,"repsMax":15,"durationSeconds":null}') ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO fitness_exercise(id,data) VALUES('calf-raise','{"id":"calf-raise","nameZh":"站姿提踵","nameEn":"Standing Calf Raises","primaryMuscle":"小腿肌群","secondaryMuscles":[],"equipment":["固定力量器械"],"difficulty":"初级","locations":["健身房"],"type":"力量","pattern":"push","instructions":["调好器械，前脚掌踩稳踏板，身体保持直立。","脚跟缓慢下沉，再通过脚踝抬起身体。","在顶端短暂停顿后控制下降。"],"commonMistakes":["上下弹跳借助惯性。","只做很小幅度或脚踝向外翻。"],"mediaUrl":"/static/fitness/media/calf-raise-0.jpg","mediaFrames":["/static/fitness/media/calf-raise-0.jpg","/static/fitness/media/calf-raise-1.jpg"],"muscleImageUrl":"","source":"Free Exercise DB；中文说明由本站整理","sourceUrl":"https://github.com/yuhonas/free-exercise-db/blob/a859101d633a01c4a1a920d6a8ce41dabba0705f/exercises/Standing_Calf_Raises.json","license":"Unlicense","recommendedSets":2,"repsMin":12,"repsMax":20,"durationSeconds":null}') ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO fitness_exercise(id,data) VALUES('hanging-leg-raise','{"id":"hanging-leg-raise","nameZh":"悬垂举腿","nameEn":"Hanging Leg Raise","primaryMuscle":"腹直肌","secondaryMuscles":["髂腰肌","前臂肌群"],"equipment":["单杠"],"difficulty":"中级","locations":["家里","健身房","户外"],"type":"核心","pattern":"core","instructions":["握稳单杠，保持肩部与躯干受控。","收紧腹部，抬起双腿并轻轻卷起骨盆。","缓慢放下，减少摆动；需要时屈膝降低难度。"],"commonMistakes":["前后摆荡借力。","只屈髋而腹部始终松弛。"],"mediaUrl":"/static/fitness/media/hanging-leg-raise-0.jpg","mediaFrames":["/static/fitness/media/hanging-leg-raise-0.jpg","/static/fitness/media/hanging-leg-raise-1.jpg"],"muscleImageUrl":"","source":"Free Exercise DB；中文说明由本站整理","sourceUrl":"https://github.com/yuhonas/free-exercise-db/blob/a859101d633a01c4a1a920d6a8ce41dabba0705f/exercises/Hanging_Leg_Raise.json","license":"Unlicense","recommendedSets":3,"repsMin":8,"repsMax":15,"durationSeconds":null}') ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO fitness_exercise(id,data) VALUES('pull-up','{"id":"pull-up","nameZh":"引体向上","nameEn":"Pullups","primaryMuscle":"背阔肌","secondaryMuscles":["肱二头肌","菱形肌","前臂肌群"],"equipment":["单杠"],"difficulty":"中级","locations":["家里","健身房","户外"],"type":"力量","pattern":"pull","instructions":["正握单杠，稳定肩胛并收紧躯干。","屈肘向上拉，直到下巴接近或超过杠面。","控制下降，每组保留余力并记录实际次数。"],"commonMistakes":["蹬腿摆荡借力。","伸脖子凑高度或下降时突然失控。"],"mediaUrl":"/static/fitness/media/pull-up-0.jpg","mediaFrames":["/static/fitness/media/pull-up-0.jpg","/static/fitness/media/pull-up-1.jpg"],"muscleImageUrl":"","source":"Free Exercise DB；中文说明由本站整理","sourceUrl":"https://github.com/yuhonas/free-exercise-db/blob/a859101d633a01c4a1a920d6a8ce41dabba0705f/exercises/Pullups.json","license":"Unlicense","recommendedSets":3,"repsMin":0,"repsMax":0,"durationSeconds":null}') ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO fitness_exercise(id,data) VALUES('lat-pulldown','{"id":"lat-pulldown","nameZh":"高位下拉","nameEn":"Wide-Grip Lat Pulldown","primaryMuscle":"背阔肌","secondaryMuscles":["肱二头肌","菱形肌"],"equipment":["龙门架 / 绳索器械"],"difficulty":"初级","locations":["健身房"],"type":"力量","pattern":"pull","instructions":["坐稳并固定大腿，握住上方拉杆。","胸部自然抬起，将拉杆拉向上胸前方。","控制伸臂还原，保持躯干稳定。"],"commonMistakes":["向颈后拉杆。","大幅后仰，用惯性拉动重量。"],"mediaUrl":"/static/fitness/media/lat-pulldown-0.jpg","mediaFrames":["/static/fitness/media/lat-pulldown-0.jpg","/static/fitness/media/lat-pulldown-1.jpg"],"muscleImageUrl":"","source":"Free Exercise DB；中文说明由本站整理","sourceUrl":"https://github.com/yuhonas/free-exercise-db/blob/a859101d633a01c4a1a920d6a8ce41dabba0705f/exercises/Wide-Grip_Lat_Pulldown.json","license":"Unlicense","recommendedSets":3,"repsMin":8,"repsMax":12,"durationSeconds":null}') ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO fitness_exercise(id,data) VALUES('seated-row','{"id":"seated-row","nameZh":"坐姿绳索划船","nameEn":"Seated Cable Rows","primaryMuscle":"背阔肌","secondaryMuscles":["菱形肌","斜方肌","肱二头肌"],"equipment":["龙门架 / 绳索器械"],"difficulty":"初级","locations":["健身房"],"type":"力量","pattern":"pull","instructions":["双脚踩稳踏板，坐直并握住手柄。","肘部向后，将手柄拉至腹部附近。","缓慢伸臂，保持腰背稳定。"],"commonMistakes":["躯干大幅前后摇摆。","耸肩或用手腕卷动手柄。"],"mediaUrl":"/static/fitness/media/seated-row-0.jpg","mediaFrames":["/static/fitness/media/seated-row-0.jpg","/static/fitness/media/seated-row-1.jpg"],"muscleImageUrl":"","source":"Free Exercise DB；中文说明由本站整理","sourceUrl":"https://github.com/yuhonas/free-exercise-db/blob/a859101d633a01c4a1a920d6a8ce41dabba0705f/exercises/Seated_Cable_Rows.json","license":"Unlicense","recommendedSets":3,"repsMin":8,"repsMax":12,"durationSeconds":null}') ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO fitness_exercise(id,data) VALUES('reverse-fly','{"id":"reverse-fly","nameZh":"胸托反向飞鸟","nameEn":"Reverse Flyes","primaryMuscle":"三角肌后束","secondaryMuscles":["菱形肌","斜方肌"],"equipment":["哑铃","训练凳"],"difficulty":"初级","locations":["家里","宿舍","健身房"],"type":"力量","pattern":"pull","instructions":["胸腹贴在上斜训练凳上，双手持哑铃自然垂下。","肘部微屈，双臂向两侧展开。","在肩部舒适范围内停顿，然后缓慢收回。"],"commonMistakes":["用过重哑铃甩动。","耸肩或把动作变成屈肘划船。"],"mediaUrl":"/static/fitness/media/reverse-fly-0.jpg","mediaFrames":["/static/fitness/media/reverse-fly-0.jpg","/static/fitness/media/reverse-fly-1.jpg"],"muscleImageUrl":"","source":"Free Exercise DB；中文说明由本站整理","sourceUrl":"https://github.com/yuhonas/free-exercise-db/blob/a859101d633a01c4a1a920d6a8ce41dabba0705f/exercises/Reverse_Flyes.json","license":"Unlicense","recommendedSets":3,"repsMin":12,"repsMax":20,"durationSeconds":null}') ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO fitness_exercise(id,data) VALUES('biceps-curl','{"id":"biceps-curl","nameZh":"哑铃二头弯举","nameEn":"Dumbbell Bicep Curl","primaryMuscle":"肱二头肌","secondaryMuscles":["前臂肌群"],"equipment":["哑铃"],"difficulty":"初级","locations":["家里","宿舍","健身房"],"type":"力量","pattern":"pull","instructions":["站稳持哑铃，掌心朝前，上臂靠近身体。","上臂保持稳定，屈肘向上弯举。","缓慢伸肘还原，保持手腕自然。"],"commonMistakes":["后仰或摆动身体借力。","肘部向前大幅移动。"],"mediaUrl":"/static/fitness/media/biceps-curl-0.jpg","mediaFrames":["/static/fitness/media/biceps-curl-0.jpg","/static/fitness/media/biceps-curl-1.jpg"],"muscleImageUrl":"","source":"Free Exercise DB；中文说明由本站整理","sourceUrl":"https://github.com/yuhonas/free-exercise-db/blob/a859101d633a01c4a1a920d6a8ce41dabba0705f/exercises/Dumbbell_Bicep_Curl.json","license":"Unlicense","recommendedSets":2,"repsMin":10,"repsMax":15,"durationSeconds":null}') ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO fitness_exercise(id,data) VALUES('pallof-press','{"id":"pallof-press","nameZh":"Pallof 抗旋转推","nameEn":"Pallof Press","primaryMuscle":"腹斜肌","secondaryMuscles":["腹直肌","三角肌"],"equipment":["龙门架 / 绳索器械"],"difficulty":"初级","locations":["健身房"],"type":"核心","pattern":"core","instructions":["侧对绳索站稳，双手将手柄握在胸前。","收紧腹部，把手柄向前推出，抵抗身体旋转。","短暂停顿后收回，两侧分别完成并记录实际次数。"],"commonMistakes":["躯干跟随拉力旋转。","屏住呼吸或腰部后仰。"],"mediaUrl":"/static/fitness/media/pallof-press-0.jpg","mediaFrames":["/static/fitness/media/pallof-press-0.jpg","/static/fitness/media/pallof-press-1.jpg"],"muscleImageUrl":"","source":"Free Exercise DB；中文说明由本站整理","sourceUrl":"https://github.com/yuhonas/free-exercise-db/blob/a859101d633a01c4a1a920d6a8ce41dabba0705f/exercises/Pallof_Press.json","license":"Unlicense","recommendedSets":3,"repsMin":0,"repsMax":0,"durationSeconds":null}') ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO fitness_exercise(id,data) VALUES('goblet-squat','{"id":"goblet-squat","nameZh":"哑铃高脚杯深蹲","nameEn":"Dumbbell Goblet Squat","primaryMuscle":"股四头肌","secondaryMuscles":["臀大肌","腹直肌"],"equipment":["哑铃"],"difficulty":"初级","locations":["家里","宿舍","健身房"],"type":"力量","pattern":"squat","instructions":["双手将一只哑铃竖直抱在胸前，双脚站稳。","屈髋屈膝下蹲，膝盖与脚尖同向。","保持背部稳定，脚掌压地站起。"],"commonMistakes":["哑铃离身体太远。","脚跟抬起或下蹲时膝盖内扣。"],"mediaUrl":"/static/fitness/media/goblet-squat-0.png","mediaFrames":["/static/fitness/media/goblet-squat-0.png","/static/fitness/media/goblet-squat-1.png"],"muscleImageUrl":"","source":"本项目生成素材（OpenAI image generation）；中文说明由本站整理","sourceUrl":"https://openai.com/policies/terms-of-use/","license":"AI-generated project asset","recommendedSets":3,"repsMin":8,"repsMax":12,"durationSeconds":null,"video":{"url":"/static/fitness/media/kettlebell-goblet-squat.webm","type":"video/webm","poster":"/static/fitness/media/goblet-squat-0.png","source":"Wikimedia Commons · Taco fleur","sourceUrl":"https://commons.wikimedia.org/wiki/File:Kettlebell_Goblet_Squat.webm","license":"CC BY-SA 4.0","attribution":"Taco fleur","note":"连续视频为壶铃高脚杯深蹲示范；本动作使用哑铃，请结合上方哑铃静态图确认握法。"}}') ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO fitness_exercise(id,data) VALUES('single-arm-row','{"id":"single-arm-row","nameZh":"单臂哑铃划船","nameEn":"One-Arm Dumbbell Row","primaryMuscle":"背阔肌","secondaryMuscles":["菱形肌","肱二头肌"],"equipment":["哑铃","训练凳"],"difficulty":"初级","locations":["家里","宿舍","健身房"],"type":"力量","pattern":"pull","instructions":["一手与同侧膝盖支撑在稳定训练凳上，另一手持哑铃。","保持背部平稳，将肘部拉向髋部附近。","缓慢放下，完成一侧后换边；目标次数按每侧计算。"],"commonMistakes":["扭转躯干甩起哑铃。","耸肩或将肘部拉得过高。"],"mediaUrl":"/static/fitness/media/single-arm-row-0.jpg","mediaFrames":["/static/fitness/media/single-arm-row-0.jpg","/static/fitness/media/single-arm-row-1.jpg"],"muscleImageUrl":"","source":"Free Exercise DB；中文说明由本站整理","sourceUrl":"https://github.com/yuhonas/free-exercise-db/blob/a859101d633a01c4a1a920d6a8ce41dabba0705f/exercises/One-Arm_Dumbbell_Row.json","license":"Unlicense","recommendedSets":3,"repsMin":8,"repsMax":12,"durationSeconds":null}') ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO fitness_exercise(id,data) VALUES('push-up','{"id":"push-up","nameZh":"俯卧撑","nameEn":"Pushups","primaryMuscle":"胸大肌","secondaryMuscles":["肱三头肌","三角肌前束","腹直肌"],"equipment":["徒手"],"difficulty":"初级","locations":["家里","宿舍","健身房","户外"],"type":"力量","pattern":"push","instructions":["双手撑地略宽于肩，身体从头到脚保持稳定。","屈肘下放胸部，肘部自然斜向后方。","推地回到起始位置，每组保留余力并记录实际次数。"],"commonMistakes":["塌腰或臀部抬得过高。","只做局部幅度或头部前伸。"],"mediaUrl":"/static/fitness/media/push-up-0.jpg","mediaFrames":["/static/fitness/media/push-up-0.jpg","/static/fitness/media/push-up-1.jpg"],"muscleImageUrl":"","source":"Free Exercise DB；中文说明由本站整理","sourceUrl":"https://github.com/yuhonas/free-exercise-db/blob/a859101d633a01c4a1a920d6a8ce41dabba0705f/exercises/Pushups.json","license":"Unlicense","recommendedSets":2,"repsMin":0,"repsMax":0,"durationSeconds":null}') ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO fitness_exercise(id,data) VALUES('incline-walk','{"id":"incline-walk","nameZh":"坡度快走","nameEn":"Incline Treadmill Walk","primaryMuscle":"腿部肌群","secondaryMuscles":["臀大肌","小腿肌群"],"equipment":["跑步机"],"difficulty":"初级","locations":["健身房"],"type":"有氧","pattern":"cardio","instructions":["先低速步行适应跑步机，再选择舒适坡度与步速。","保持直立，手臂自然摆动，持续快走 10–15 分钟。","结束前逐渐降低速度，待跑带停止后下机。"],"commonMistakes":["长期用双手悬挂在扶手上。","坡度或速度超过当前可控范围。"],"mediaUrl":"/static/fitness/media/incline-walk-0.png","mediaFrames":["/static/fitness/media/incline-walk-0.png","/static/fitness/media/incline-walk-1.png"],"muscleImageUrl":"","source":"本项目生成素材（OpenAI image generation）；中文说明由本站整理","sourceUrl":"https://openai.com/policies/terms-of-use/","license":"AI-generated project asset","recommendedSets":1,"repsMin":0,"repsMax":0,"durationSeconds":900}') ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO fitness_exercise(id,data) VALUES('machine-shoulder-press','{"id":"machine-shoulder-press","nameZh":"器械肩推","nameEn":"Leverage Shoulder Press","primaryMuscle":"三角肌","secondaryMuscles":["肱三头肌"],"equipment":["固定力量器械"],"difficulty":"初级","locations":["健身房"],"type":"力量","pattern":"push","instructions":["调整座椅，使把手位于肩部附近。","背部贴稳靠垫，平稳向上推起把手。","控制返回，不让配重片突然撞击。"],"commonMistakes":["腰部离开靠垫过度后仰。","座椅过高或过低导致轨迹不舒服。"],"mediaUrl":"/static/fitness/media/machine-shoulder-press-0.jpg","mediaFrames":["/static/fitness/media/machine-shoulder-press-0.jpg","/static/fitness/media/machine-shoulder-press-1.jpg"],"muscleImageUrl":"","source":"Free Exercise DB；中文说明由本站整理","sourceUrl":"https://github.com/yuhonas/free-exercise-db/blob/a859101d633a01c4a1a920d6a8ce41dabba0705f/exercises/Leverage_Shoulder_Press.json","license":"Unlicense","recommendedSets":3,"repsMin":8,"repsMax":12,"durationSeconds":null}') ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO fitness_exercise(id,data) VALUES('cable-crunch','{"id":"cable-crunch","nameZh":"绳索卷腹","nameEn":"Cable Crunch","primaryMuscle":"腹直肌","secondaryMuscles":[],"equipment":["龙门架 / 绳索器械"],"difficulty":"初级","locations":["健身房"],"type":"核心","pattern":"core","instructions":["面对高位绳索跪稳，绳端放在头部两侧。","髋部相对稳定，通过卷腹让肋骨靠近骨盆。","缓慢还原上身，保持绳索张力。"],"commonMistakes":["用手臂下拉绳索。","反复坐向脚跟，以屈髋代替卷腹。"],"mediaUrl":"/static/fitness/media/cable-crunch-0.jpg","mediaFrames":["/static/fitness/media/cable-crunch-0.jpg","/static/fitness/media/cable-crunch-1.jpg"],"muscleImageUrl":"","source":"Free Exercise DB；中文说明由本站整理","sourceUrl":"https://github.com/yuhonas/free-exercise-db/blob/a859101d633a01c4a1a920d6a8ce41dabba0705f/exercises/Cable_Crunch.json","license":"Unlicense","recommendedSets":3,"repsMin":10,"repsMax":15,"durationSeconds":null}') ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO fitness_exercise(id,data) VALUES('leg-press','{"id":"leg-press","nameZh":"腿举","nameEn":"Leg Press","primaryMuscle":"股四头肌","secondaryMuscles":["臀大肌","腘绳肌"],"equipment":["固定力量器械"],"difficulty":"初级","locations":["健身房"],"type":"力量","pattern":"squat","instructions":["坐稳并将双脚放在踏板上，腰背贴好靠垫。","解除保护后，屈膝缓慢下放踏板。","在骨盆仍稳定的深度推回，结束后扣好保护装置。"],"commonMistakes":["底部骨盆卷起离开靠垫。","猛顶膝关节或膝盖向内塌陷。"],"mediaUrl":"/static/fitness/media/leg-press-0.jpg","mediaFrames":["/static/fitness/media/leg-press-0.jpg","/static/fitness/media/leg-press-1.jpg"],"muscleImageUrl":"","source":"Free Exercise DB；中文说明由本站整理","sourceUrl":"https://github.com/yuhonas/free-exercise-db/blob/a859101d633a01c4a1a920d6a8ce41dabba0705f/exercises/Leg_Press.json","license":"Unlicense","recommendedSets":3,"repsMin":6,"repsMax":10,"durationSeconds":null}') ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO fitness_exercise(id,data) VALUES('front-squat','{"id":"front-squat","nameZh":"杠铃前蹲","nameEn":"Front Barbell Squat","primaryMuscle":"股四头肌","secondaryMuscles":["臀大肌","腹直肌","竖脊肌"],"equipment":["杠铃","深蹲架"],"difficulty":"高级","locations":["健身房"],"type":"力量","pattern":"squat","instructions":["将杠铃稳定架在肩前，抬肘并收紧腹部。","保持胸部稳定，屈髋屈膝下蹲。","双脚压地起身，全程控制杠铃位置。"],"commonMistakes":["肘部下垂导致杠铃前滚。","躯干前倾失控或脚跟离地。"],"mediaUrl":"/static/fitness/media/front-squat-0.jpg","mediaFrames":["/static/fitness/media/front-squat-0.jpg","/static/fitness/media/front-squat-1.jpg"],"muscleImageUrl":"","source":"Free Exercise DB；中文说明由本站整理","sourceUrl":"https://github.com/yuhonas/free-exercise-db/blob/a859101d633a01c4a1a920d6a8ce41dabba0705f/exercises/Front_Barbell_Squat.json","license":"Unlicense","recommendedSets":3,"repsMin":8,"repsMax":12,"durationSeconds":null}') ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO fitness_exercise(id,data) VALUES('dumbbell-bench-press','{"id":"dumbbell-bench-press","nameZh":"哑铃平板卧推","nameEn":"Dumbbell Bench Press","primaryMuscle":"胸大肌","secondaryMuscles":["肱三头肌","三角肌前束"],"equipment":["哑铃","训练凳"],"difficulty":"初级","locations":["家里","宿舍","健身房"],"type":"力量","pattern":"push","instructions":["仰卧平凳，双脚踩稳，哑铃放在胸部两侧。","保持肩胛稳定，将哑铃向上推起。","缓慢下放至肩部舒适的位置。"],"commonMistakes":["两侧重量失衡或互相碰撞。","肩膀向前顶，失去肩胛稳定。"],"mediaUrl":"/static/fitness/media/dumbbell-bench-press-0.jpg","mediaFrames":["/static/fitness/media/dumbbell-bench-press-0.jpg","/static/fitness/media/dumbbell-bench-press-1.jpg"],"muscleImageUrl":"","source":"Free Exercise DB；中文说明由本站整理","sourceUrl":"https://github.com/yuhonas/free-exercise-db/blob/a859101d633a01c4a1a920d6a8ce41dabba0705f/exercises/Dumbbell_Bench_Press.json","license":"Unlicense","recommendedSets":3,"repsMin":8,"repsMax":12,"durationSeconds":null}') ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO fitness_exercise(id,data) VALUES('machine-chest-press','{"id":"machine-chest-press","nameZh":"器械推胸","nameEn":"Machine Bench Press","primaryMuscle":"胸大肌","secondaryMuscles":["肱三头肌","三角肌前束"],"equipment":["固定力量器械"],"difficulty":"初级","locations":["健身房"],"type":"力量","pattern":"push","instructions":["调整座椅，让把手与胸部高度相近。","脚踩稳，背部贴靠垫，向前推起把手。","控制手柄返回，保持肩部稳定。"],"commonMistakes":["耸肩或腰背大幅离开靠垫。","配重落下时失去控制。"],"mediaUrl":"/static/fitness/media/machine-chest-press-0.jpg","mediaFrames":["/static/fitness/media/machine-chest-press-0.jpg","/static/fitness/media/machine-chest-press-1.jpg"],"muscleImageUrl":"","source":"Free Exercise DB；中文说明由本站整理","sourceUrl":"https://github.com/yuhonas/free-exercise-db/blob/a859101d633a01c4a1a920d6a8ce41dabba0705f/exercises/Machine_Bench_Press.json","license":"Unlicense","recommendedSets":3,"repsMin":8,"repsMax":12,"durationSeconds":null}') ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO fitness_exercise(id,data) VALUES('dumbbell-fly','{"id":"dumbbell-fly","nameZh":"哑铃飞鸟","nameEn":"Dumbbell Flyes","primaryMuscle":"胸大肌","secondaryMuscles":["三角肌前束"],"equipment":["哑铃","训练凳"],"difficulty":"初级","locations":["家里","宿舍","健身房"],"type":"力量","pattern":"push","instructions":["仰卧平凳，双手持哑铃在胸前，掌心相对。","保持肘部微屈，双臂向两侧缓慢打开。","在肩部舒适范围内将哑铃沿弧线合回胸前。"],"commonMistakes":["肘部伸得过直。","下降过深或选择无法控制的重量。"],"mediaUrl":"/static/fitness/media/dumbbell-fly-0.jpg","mediaFrames":["/static/fitness/media/dumbbell-fly-0.jpg","/static/fitness/media/dumbbell-fly-1.jpg"],"muscleImageUrl":"","source":"Free Exercise DB；中文说明由本站整理","sourceUrl":"https://github.com/yuhonas/free-exercise-db/blob/a859101d633a01c4a1a920d6a8ce41dabba0705f/exercises/Dumbbell_Flyes.json","license":"Unlicense","recommendedSets":2,"repsMin":10,"repsMax":15,"durationSeconds":null}') ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO fitness_exercise(id,data) VALUES('bodyweight-squat','{"id":"bodyweight-squat","nameZh":"徒手深蹲","nameEn":"Bodyweight Squat","primaryMuscle":"股四头肌","secondaryMuscles":["臀大肌"],"equipment":["徒手"],"difficulty":"初级","locations":["家里","宿舍","健身房","户外"],"type":"力量","pattern":"squat","instructions":["双脚站稳，脚尖自然向外。","臀部向后下方移动，膝盖与脚尖同向。","在能保持平衡的深度停止，平稳站起。"],"commonMistakes":["膝盖内扣。","脚跟离地或上身塌陷。"],"mediaUrl":"/static/fitness/media/bodyweight-squat-0.jpg","mediaFrames":["/static/fitness/media/bodyweight-squat-0.jpg","/static/fitness/media/bodyweight-squat-1.jpg"],"muscleImageUrl":"","source":"Free Exercise DB；中文说明由本站整理","sourceUrl":"https://github.com/yuhonas/free-exercise-db/blob/a859101d633a01c4a1a920d6a8ce41dabba0705f/exercises/Bodyweight_Squat.json","license":"Unlicense","recommendedSets":3,"repsMin":12,"repsMax":20,"durationSeconds":null}') ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO fitness_exercise(id,data) VALUES('glute-bridge','{"id":"glute-bridge","nameZh":"臀桥","nameEn":"Butt Lift (Bridge)","primaryMuscle":"臀大肌","secondaryMuscles":["腘绳肌","腹直肌"],"equipment":["徒手"],"difficulty":"初级","locations":["家里","宿舍","健身房","户外"],"type":"力量","pattern":"hinge","instructions":["仰卧屈膝，双脚踩地与髋同宽。","收紧腹部并用臀部抬起髋部。","肩、髋、膝接近一线时停顿，再缓慢放下。"],"commonMistakes":["用腰部过度反弓顶高身体。","膝盖向内塌陷。"],"mediaUrl":"/static/fitness/media/glute-bridge-0.jpg","mediaFrames":["/static/fitness/media/glute-bridge-0.jpg","/static/fitness/media/glute-bridge-1.jpg"],"muscleImageUrl":"","source":"Free Exercise DB；中文说明由本站整理","sourceUrl":"https://github.com/yuhonas/free-exercise-db/blob/a859101d633a01c4a1a920d6a8ce41dabba0705f/exercises/Butt_Lift_Bridge.json","license":"Unlicense","recommendedSets":3,"repsMin":10,"repsMax":15,"durationSeconds":null}') ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO fitness_exercise(id,data) VALUES('hammer-curl','{"id":"hammer-curl","nameZh":"哑铃锤式弯举","nameEn":"Hammer Curls","primaryMuscle":"肱二头肌","secondaryMuscles":["肱肌","前臂肌群"],"equipment":["哑铃"],"difficulty":"初级","locations":["家里","宿舍","健身房"],"type":"力量","pattern":"pull","instructions":["站稳持哑铃，掌心相对，上臂靠近身体。","保持中立握法，屈肘将哑铃提起。","缓慢还原，左右保持同样幅度。"],"commonMistakes":["摆动躯干借力。","手腕弯折或肘部大幅前移。"],"mediaUrl":"/static/fitness/media/hammer-curl-0.jpg","mediaFrames":["/static/fitness/media/hammer-curl-0.jpg","/static/fitness/media/hammer-curl-1.jpg"],"muscleImageUrl":"","source":"Free Exercise DB；中文说明由本站整理","sourceUrl":"https://github.com/yuhonas/free-exercise-db/blob/a859101d633a01c4a1a920d6a8ce41dabba0705f/exercises/Hammer_Curls.json","license":"Unlicense","recommendedSets":2,"repsMin":10,"repsMax":15,"durationSeconds":null}') ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO fitness_exercise(id,data) VALUES('plank','{"id":"plank","nameZh":"平板支撑","nameEn":"Plank","primaryMuscle":"腹直肌","secondaryMuscles":["腹斜肌","臀大肌"],"equipment":["徒手"],"difficulty":"初级","locations":["家里","宿舍","健身房","户外"],"type":"核心","pattern":"core","instructions":["前臂撑地，肘部在肩部下方，脚尖支撑。","收紧腹部与臀部，头、躯干和双腿保持一线。","自然呼吸，保持可控姿势并记录持续时间。"],"commonMistakes":["塌腰或抬臀。","屏住呼吸或耸肩。"],"mediaUrl":"/static/fitness/media/plank-0.jpg","mediaFrames":["/static/fitness/media/plank-0.jpg","/static/fitness/media/plank-1.jpg"],"muscleImageUrl":"","source":"Free Exercise DB；中文说明由本站整理","sourceUrl":"https://github.com/yuhonas/free-exercise-db/blob/a859101d633a01c4a1a920d6a8ce41dabba0705f/exercises/Plank.json","license":"Unlicense","recommendedSets":3,"repsMin":0,"repsMax":0,"durationSeconds":30}') ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO fitness_exercise(id,data) VALUES('dead-bug','{"id":"dead-bug","nameZh":"死虫式","nameEn":"Dead Bug","primaryMuscle":"腹直肌","secondaryMuscles":["腹斜肌"],"equipment":["徒手"],"difficulty":"初级","locations":["家里","宿舍","健身房","户外"],"type":"核心","pattern":"core","instructions":["仰卧，双臂向上，髋膝屈曲抬起双腿。","保持腰背稳定，缓慢伸出一条腿至接近地面。","收回后换腿；目标次数按每侧计算。"],"commonMistakes":["伸腿时腰部明显拱起。","动作过快，无法稳定骨盆。"],"mediaUrl":"/static/fitness/media/dead-bug-0.jpg","mediaFrames":["/static/fitness/media/dead-bug-0.jpg","/static/fitness/media/dead-bug-1.jpg"],"muscleImageUrl":"","source":"Free Exercise DB；中文说明由本站整理","sourceUrl":"https://github.com/yuhonas/free-exercise-db/blob/a859101d633a01c4a1a920d6a8ce41dabba0705f/exercises/Dead_Bug.json","license":"Unlicense","recommendedSets":3,"repsMin":8,"repsMax":12,"durationSeconds":null}') ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO fitness_exercise(id,data) VALUES('seated-leg-curl','{"id":"seated-leg-curl","nameZh":"坐姿腿弯举","nameEn":"Seated Leg Curl","primaryMuscle":"腘绳肌","secondaryMuscles":["小腿肌群"],"equipment":["固定力量器械"],"difficulty":"初级","locations":["健身房"],"type":"力量","pattern":"hinge","instructions":["调整器械，使膝部对齐转轴并压稳大腿。","保持身体靠稳，通过屈膝向下后方卷动滚垫。","缓慢伸膝回到起始位置。"],"commonMistakes":["臀部离开座椅。","过快松回配重。"],"mediaUrl":"/static/fitness/media/seated-leg-curl-0.jpg","mediaFrames":["/static/fitness/media/seated-leg-curl-0.jpg","/static/fitness/media/seated-leg-curl-1.jpg"],"muscleImageUrl":"","source":"Free Exercise DB；中文说明由本站整理","sourceUrl":"https://github.com/yuhonas/free-exercise-db/blob/a859101d633a01c4a1a920d6a8ce41dabba0705f/exercises/Seated_Leg_Curl.json","license":"Unlicense","recommendedSets":2,"repsMin":10,"repsMax":15,"durationSeconds":null}') ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO fitness_exercise(id,data) VALUES('inverted-row','{"id":"inverted-row","nameZh":"自重反向划船","nameEn":"Inverted Row","primaryMuscle":"背阔肌","secondaryMuscles":["菱形肌","肱二头肌","腹直肌"],"equipment":["单杠"],"difficulty":"初级","locations":["健身房","户外"],"type":"力量","pattern":"pull","instructions":["选择固定牢靠的低杠，仰身握杠并踩稳双脚。","保持身体成线，将胸部拉向杠。","控制伸臂下降；身体越直立越容易。"],"commonMistakes":["塌腰或用髋部上顶借力。","使用会滚动或松脱的支撑。"],"mediaUrl":"/static/fitness/media/inverted-row-0.jpg","mediaFrames":["/static/fitness/media/inverted-row-0.jpg","/static/fitness/media/inverted-row-1.jpg"],"muscleImageUrl":"","source":"Free Exercise DB；中文说明由本站整理","sourceUrl":"https://github.com/yuhonas/free-exercise-db/blob/a859101d633a01c4a1a920d6a8ce41dabba0705f/exercises/Inverted_Row.json","license":"Unlicense","recommendedSets":3,"repsMin":8,"repsMax":12,"durationSeconds":null}') ON CONFLICT(id) DO UPDATE SET data=excluded.data;
